def build_ds_fn(
    is_training: bool, *, texts: Sequence[str], data_dir: Optional[str] = None
) -> BuildDatasetFn:
    del is_training, data_dir

    def ds_fn() -> tf.data.Dataset:
        def data_gen():
            for text in texts:
