        def data_gen():
            for value in self.DEFAULT_VALUES:
                yield {"key1": value, "key2": value}

        return tf.data.Dataset.from_generator(
            data_gen,
            output_signature={
                "key1": tf.TensorSpec(shape=(), dtype=tf.string),
                "key2": tf.TensorSpec(shape=(), dtype=tf.string),
            },
        )

