        ds = self._ds_fn()
        ds = rekey(
            {"new_key1": "key1", "new_key2": "key2", "new_key3": "key3"}, default_value="no"
        )(ds)
        for ix, el in enumerate(ds):
            self.assertEqual(set(el.keys()), {"new_key1", "new_key2", "new_key3"})
